import { useState } from "react";
import axios from "axios";

function App() {
  const [input, setInput] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim()) return;

    setLoading(true);
    setResponse(""); // Clear previous response
    try {
      const res = await axios.post("http://localhost:5000/chat", {
        prompt: input,
      });
      setResponse(res.data.response.parts[0].text);
    } catch (error) {
      console.error("Error:", error);
      setResponse("Error fetching response. Check console.");
    } finally {
      setLoading(false);
    }
  };

  const handleClear = () => {
    setInput("");
    setResponse("");
  };

  return (
    <div style={styles.container}>
      <div style={styles.chatBox}>
        <h2 style={styles.title}>AI Tutor 🤖</h2>
        <textarea
          style={styles.textarea}
          rows="4"
          cols="50"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask me anything..."
        />
        <div style={styles.buttonContainer}>
          <button onClick={handleSend} style={styles.askButton}>
            Ask AI
          </button>
          <button onClick={handleClear} style={styles.clearButton}>
            Clear Chat
          </button>
        </div>
        <h3 style={styles.responseTitle}>Response:</h3>

        {loading ? (
          <div style={styles.loaderContainer}>
            <div style={styles.loader}></div>
            <p style={styles.loadingText}>Generating response...</p>
          </div>
        ) : (
          <div style={styles.responseBox}>{response}</div>
        )}
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "100vh",
    background: "linear-gradient(to right, #2c3e50, #4ca1af)",
  },
  chatBox: {
    background: "#fff",
    padding: "20px",
    borderRadius: "10px",
    boxShadow: "0 4px 8px rgba(0,0,0,0.2)",
    width: "50%",
    minWidth: "400px",
    textAlign: "center",
  },
  title: {
    fontSize: "24px",
    fontWeight: "bold",
    color: "#2c3e50",
    marginBottom: "15px",
  },
  textarea: {
    width: "100%",
    padding: "10px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    fontSize: "16px",
    resize: "none",
    outline: "none",
  },
  buttonContainer: {
    marginTop: "10px",
    display: "flex",
    justifyContent: "space-between",
  },
  askButton: {
    padding: "10px 20px",
    background: "#27ae60",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
    fontSize: "16px",
    transition: "0.3s",
  },
  clearButton: {
    padding: "10px 20px",
    background: "#e74c3c",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
    fontSize: "16px",
    transition: "0.3s",
  },
  responseTitle: {
    marginTop: "20px",
    fontSize: "18px",
    fontWeight: "bold",
    color: "#2c3e50",
  },
  responseBox: {
    marginTop: "10px",
    padding: "10px",
    borderRadius: "5px",
    background: "#ecf0f1",
    textAlign: "left",
    minHeight: "50px",
    whiteSpace: "pre-wrap",
    fontSize: "16px",
  },
  loaderContainer: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: "10px",
  },
  loader: {
    width: "40px",
    height: "40px",
    border: "5px solid #f3f3f3",
    borderTop: "5px solid #3498db",
    borderRadius: "50%",
    animation: "spin 1s linear infinite",
  },
  loadingText: {
    marginTop: "5px",
    fontSize: "14px",
    color: "#3498db",
  },
};

// CSS Animation for Spinner
const styleSheet = document.styleSheets[0];
styleSheet.insertRule(`
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`, styleSheet.cssRules.length);

export default App;
